import sys

import pyBigWig


def main():
    if len(sys.argv) != 3:
        raise SystemExit("usage: diagnostic.py INPUT_BIGWIG OUTPUT_TSV")

    input_path, output_path = sys.argv[1:]
    with pyBigWig.open(input_path) as bw, open(output_path, "w", encoding="utf-8") as out:
        out.write("# diagnostic\n")
        out.write("# chromosome lengths from bigWig\n")
        for chrom in [f"chr{i}" for i in range(1, 20)]:
            length = bw.chroms().get(chrom)
            if length is not None:
                out.write(f"chrom\t{chrom}\t{length}\n")

        out.write("# first three full 1Mbp windows on chr1 and chr2\n")
        out.write("window\tchrom\tstart\tend\tsum_exact\tmean_exact\tcoverage_exact\tmean_times_length\n")
        for chrom in ("chr1", "chr2"):
            length = bw.chroms().get(chrom)
            if length is None:
                continue
